class ActivateFile(GenericEMSSIMCommand):
    """Activatefile command class."""

    def __init__(self, connection, file_type, plan_id, prompt=None, newline_chars=None, runner=None):
        """
        Activatefile command.

        :param connection: moler connection to device, terminal when command is executed.
        :param file_type: number of file type
        :param plan_id: number of plan id
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ActivateFile, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.file_type = file_type
        self.plan_id = plan_id
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return f'activate_file {self.file_type} {self.plan_id}'


